package main

import (
	"encoding/json"
	"flag"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"

	tea "github.com/charmbracelet/bubbletea"
	"gopkg.in/yaml.v3"
	"github.com/BurntSushi/toml"
)

const version = "39.2.0"

func main() {
	// Define flags
	helpFlag := flag.Bool("help", false, "print help")
	hShort := flag.Bool("h", false, "print help")
	versionFlag := flag.Bool("version", false, "print version")
	vShort := flag.Bool("v", false, "print version")
	themesFlag := flag.Bool("themes", false, "print themes")
	rawFlag := flag.Bool("r", false, "treat input as a raw string")
	slurpFlag := flag.Bool("s", false, "read all inputs into an array")
	yamlFlag := flag.Bool("yaml", false, "parse input as YAML")
	tomlFlag := flag.Bool("toml", false, "parse input as TOML")
	strictFlag := flag.Bool("strict", false, "strict mode")
	noInlineFlag := flag.Bool("no-inline", false, "disable inlining in output")
	gameOfLifeFlag := flag.Bool("game-of-life", false, "play the game of life")
	compFlag := flag.String("comp", "", "print completion script")

	flag.Parse()

	// Handle help flag
	if *helpFlag || *hShort {
		printHelp()
		os.Exit(0)
	}

	// Handle version flag
	if *versionFlag || *vShort {
		fmt.Println(version)
		os.Exit(0)
	}

	// Handle themes flag
	if *themesFlag {
		printThemes()
		os.Exit(0)
	}

	// Handle completion flag
	if *compFlag != "" {
		printCompletion(*compFlag)
		os.Exit(0)
	}

	// Get remaining args (files and query)
	args := flag.Args()

	// Read input
	var input []byte
	var err error
	var filename string

	if len(args) == 0 {
		// Read from stdin
		input, err = io.ReadAll(os.Stdin)
	} else {
		// Read from file
		filename = args[0]
		input, err = os.ReadFile(filename)
	}

	if err != nil {
		fmt.Fprintf(os.Stderr, "Error reading input: %v\n", err)
		os.Exit(1)
	}

	// Parse input
	var data interface{}

	if *rawFlag {
		data = string(input)
	} else if *yamlFlag {
		err = yaml.Unmarshal(input, &data)
	} else if *tomlFlag {
		err = toml.Unmarshal(input, &data)
	} else {
		err = json.Unmarshal(input, &data)
	}

	if err != nil && !*strictFlag {
		// Try to handle as raw string if JSON parsing fails
		data = string(input)
	} else if err != nil {
		fmt.Fprintf(os.Stderr, "Error parsing input: %v\n", err)
		os.Exit(1)
	}

	// Start TUI
	opts := []tea.ProgramOption{
		tea.WithAltScreen(),
		tea.WithMouseCellMotion(),
	}

	m := NewModel(data, filename, *noInlineFlag)
	p := tea.NewProgram(m, opts...)

	if _, err := p.Run(); err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		os.Exit(1)
	}
}

func printHelp() {
	help := `
  fx 39.2.0
    Terminal JSON viewer

  Usage
    fx data.json
    fx data.json .field
    curl ... | fx

  Flags
    -h, --help            print help
    -v, --version         print version
    --themes              print themes
    --comp <shell>        print completion script
    -r, --raw             treat input as a raw string
    -s, --slurp           read all inputs into an array
    --yaml                parse input as YAML
    --toml                parse input as TOML
    --strict              strict mode
    --no-inline           disable inlining in output
    --game-of-life        play the game of life

  More info
    https://fx.wtf

  Author
    Anton Medvedev <anton@medv.io>
`
	fmt.Print(help)
}

func printThemes() {
	themes := []struct {
		num   string
		label string
	}{
		{"0", "Theme 0"},
		{"1", "Theme 1"},
		{"2", "Theme 2"},
		{"3", "Theme 3"},
		{"4", "Theme 4"},
		{"5", "Theme 5"},
		{"6", "Theme 6"},
		{"7", "Theme 7"},
		{"8", "Theme 8"},
		{"9", "Theme 9"},
		{"🔥", "Fire"},
		{"🔵", "Blue"},
	}

	data := map[string]interface{}{
		"string":    "Fox jumps over the lazy dog",
		"number":    1234567890,
		"boolean":   true,
		"null":      nil,
		"collapsed": map[string]interface{}{"preview": "…"},
	}

	jsonData, _ := json.MarshalIndent(data, "", "  ")

	for _, theme := range themes {
		fmt.Printf("export FX_THEME=\"%s\"\n", theme.num)
		fmt.Println(string(jsonData))
		fmt.Println()
	}
}

func printCompletion(shell string) {
	switch shell {
	case "bash":
		fmt.Println("complete -o filenames -C fx fx")
	case "zsh":
		zshCompletion := `#compdef fx

_fx() {
    local -a reply
    reply=("${(@f)$(COMP_ZSH="${LBUFFER}" fx)}")
    if (( ${#reply} )); then
        local -a insert_files display_files insert_other display_other
        local line display rest value typ

        for line in "${reply[@]}"; do
            display="${line%%$'\t'*}"
            rest="${line#*$'\t'}"
            value="${rest%%$'\t'*}"
            typ="${rest#*$'\t'}"

            if [[ "$typ" == "file" ]]; then
                display_files+=("$display")
                insert_files+=("$value")
            else
                display_other+=("$display")
                insert_other+=("$value")
            fi
        done

        if (( ${#insert_files} )); then
            compadd -f -d display_files -a insert_files
        fi
        if (( ${#insert_other} )); then
            compadd -S '' -d display_other -a insert_other
        fi
    fi
}

if [ "$funcstack[1]" = "_fx" ]; then
    _fx "$@"
else
    compdef _fx fx
fi`
		fmt.Println(zshCompletion)
	case "fish":
		fmt.Println("complete --command fx --arguments '(COMP_FISH=(commandline -cp) fx)'")
	}
}
EOF

