package main

import (
	"encoding/json"
	"fmt"
	"strings"

	tea "github.com/charmbracelet/bubbletea"
	"github.com/charmbracelet/lipgloss"
)

type Model struct {
	data       interface{}
	filename   string
	noInline   bool
	width      int
	height     int
	offset     int
	lines      []string
	selected   int
	expandPath map[string]bool
}

func NewModel(data interface{}, filename string, noInline bool) *Model {
	m := &Model{
		data:       data,
		filename:   filename,
		noInline:   noInline,
		expandPath: make(map[string]bool),
	}
	m.renderLines()
	return m
}

func (m *Model) Init() tea.Cmd {
	return nil
}

func (m *Model) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	switch msg := msg.(type) {
	case tea.WindowSizeMsg:
		m.width = msg.Width
		m.height = msg.Height
		m.renderLines()

	case tea.KeyMsg:
		switch msg.String() {
		case "ctrl+c", "q":
			return m, tea.Quit
		case "up", "k":
			if m.selected > 0 {
				m.selected--
			}
		case "down", "j":
			if m.selected < len(m.lines)-1 {
				m.selected++
			}
		case "home":
			m.selected = 0
		case "end":
			if len(m.lines) > 0 {
				m.selected = len(m.lines) - 1
			}
		case "page_up":
			m.selected = max(0, m.selected-(m.height-2))
		case "page_down":
			m.selected = min(len(m.lines)-1, m.selected+(m.height-2))
		}
	}

	return m, nil
}

func (m *Model) View() string {
	if len(m.lines) == 0 {
		return ""
	}

	var view strings.Builder

	// Calculate visible range
	startLine := 0
	if m.selected >= m.height-2 {
		startLine = m.selected - (m.height - 3)
	}
	endLine := min(len(m.lines), startLine+(m.height-2))

	// Draw lines
	for i := startLine; i < endLine; i++ {
		line := m.lines[i]
		if i == m.selected {
			view.WriteString(lipgloss.NewStyle().
				Background(lipgloss.Color("8")).
				Foreground(lipgloss.Color("15")).
				Render(line))
		} else {
			view.WriteString(line)
		}
		view.WriteString("\n")
	}

	// Fill remaining space with tildes
	for i := endLine - startLine; i < m.height-2; i++ {
		view.WriteString("~\n")
	}

	// Status bar
	percentage := 1
	if len(m.lines) > 0 {
		percentage = (m.selected * 100) / len(m.lines)
	}
	status := fmt.Sprintf("%d%%", percentage)
	if m.filename != "" {
		status = fmt.Sprintf("%d%% %s", percentage, m.filename)
	}

	statusLine := lipgloss.NewStyle().
		Background(lipgloss.Color("8")).
		Foreground(lipgloss.Color("15")).
		Render(fmt.Sprintf("%-*s", m.width, status))
	view.WriteString(statusLine)

	return view.String()
}

func (m *Model) renderLines() {
	jsonBytes, _ := json.MarshalIndent(m.data, "", "  ")
	text := string(jsonBytes)
	m.lines = strings.Split(text, "\n")

	// Remove last empty line if present
	if len(m.lines) > 0 && m.lines[len(m.lines)-1] == "" {
		m.lines = m.lines[:len(m.lines)-1]
	}
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func max(a, b int) int {
	if a > b {
		return a
	}
	return b
}
EOF

