package main

import (
	"encoding/json"
	"fmt"
	"os"
	"os/signal"
	"strings"
	"syscall"
	"unsafe"
)

type TUI struct {
	data       interface{}
	filename   string
	noInline   bool
	lines      []string
	selected   int
	width      int
	height     int
	termios    syscall.Termios
	oldTermios syscall.Termios
}

func NewTUI(data interface{}, filename string, noInline bool) *TUI {
	t := &TUI{
		data:     data,
		filename: filename,
		noInline: noInline,
	}
	t.renderLines()
	return t
}

func (t *TUI) renderLines() {
	jsonBytes, _ := json.MarshalIndent(t.data, "", "  ")
	text := string(jsonBytes)
	t.lines = strings.Split(text, "\n")

	// Remove last empty line if present
	if len(t.lines) > 0 && t.lines[len(t.lines)-1] == "" {
		t.lines = t.lines[:len(t.lines)-1]
	}
}

func (t *TUI) Run() error {
	// Check if stdin is a TTY
	fd := int(os.Stdin.Fd())
	_, err := os.Stdin.Stat()
	if err != nil {
		return fmt.Errorf("could not stat stdin: %v", err)
	}

	// Try to get terminal size
	if err := t.getTerminalSize(); err != nil {
		return fmt.Errorf("could not get terminal size: %v", err)
	}

	// Setup raw mode
	if err := t.enableRawMode(); err != nil {
		return fmt.Errorf("could not enable raw mode: %v", err)
	}
	defer t.disableRawMode()

	// Setup signal handling
	sigChan := make(chan os.Signal, 1)
	signal.Notify(sigChan, syscall.SIGWINCH, syscall.SIGINT, syscall.SIGTERM)
	defer signal.Stop(sigChan)

	// Main loop
	for {
		t.draw()

		// Read key
		buf := make([]byte, 3)
		n, err := os.Stdin.Read(buf)
		if err != nil {
			break
		}

		if n == 0 {
			continue
		}

		// Handle keys
		if n == 1 {
			key := buf[0]
			switch key {
			case 3: // Ctrl+C
				return nil
			case 'q':
				return nil
			case 'j': // Down
				if t.selected < len(t.lines)-1 {
					t.selected++
				}
			case 'k': // Up
				if t.selected > 0 {
					t.selected--
				}
			case 'G': // End
				if len(t.lines) > 0 {
					t.selected = len(t.lines) - 1
				}
			case 'g': // Home (first g of gg)
				// This would need a second key, for now just go home
				t.selected = 0
			}
		} else if n == 3 && buf[0] == 27 && buf[1] == 91 { // Escape sequence
			key := buf[2]
			switch key {
			case 'B': // Down arrow
				if t.selected < len(t.lines)-1 {
					t.selected++
				}
			case 'A': // Up arrow
				if t.selected > 0 {
					t.selected--
				}
			case 'H': // Home
				t.selected = 0
			case 'F': // End
				if len(t.lines) > 0 {
					t.selected = len(t.lines) - 1
				}
			}
		}

		// Check for signals
		select {
		case sig := <-sigChan:
			if sig == syscall.SIGWINCH {
				t.getTerminalSize()
			} else {
				return nil
			}
		default:
		}
	}

	return nil
}

func (t *TUI) getTerminalSize() error {
	ws := &struct {
		Row    uint16
		Col    uint16
		Xpixel uint16
		Ypixel uint16
	}{}

	retCode, _, errno := syscall.Syscall(syscall.SYS_IOCTL,
		uintptr(os.Stdout.Fd()),
		uintptr(syscall.TIOCGWINSZ),
		uintptr(unsafe.Pointer(ws)))

	if int(retCode) < 0 {
		return fmt.Errorf("ioctl error: %v", errno)
	}

	t.width = int(ws.Col)
	t.height = int(ws.Row)
	return nil
}

func (t *TUI) enableRawMode() error {
	fd := int(os.Stdin.Fd())

	// Get current settings
	if _, _, err := syscall.Syscall(syscall.SYS_IOCTL, uintptr(fd), syscall.TCGETS, uintptr(unsafe.Pointer(&t.oldTermios))); err != 0 {
		return fmt.Errorf("TCGETS error: %v", err)
	}

	t.termios = t.oldTermios

	// Disable canonical mode and echo
	t.termios.Lflag &= ^uint32(syscall.ICANON | syscall.ECHO)
	t.termios.Cc[syscall.VMIN] = 1
	t.termios.Cc[syscall.VTIME] = 0

	// Set new settings
	if _, _, err := syscall.Syscall(syscall.SYS_IOCTL, uintptr(fd), syscall.TCSETS, uintptr(unsafe.Pointer(&t.termios))); err != 0 {
		return fmt.Errorf("TCSETS error: %v", err)
	}

	return nil
}

func (t *TUI) disableRawMode() error {
	fd := int(os.Stdin.Fd())
	_, _, err := syscall.Syscall(syscall.SYS_IOCTL, uintptr(fd), syscall.TCSETS, uintptr(unsafe.Pointer(&t.oldTermios)))
	if err != 0 {
		return fmt.Errorf("TCSETS error: %v", err)
	}
	return nil
}

func (t *TUI) draw() {
	// Clear screen
	fmt.Print("\x1b[2J")
	// Move cursor to home
	fmt.Print("\x1b[H")

	// Calculate visible range
	startLine := 0
	if t.selected >= t.height-2 {
		startLine = t.selected - (t.height - 3)
	}
	if startLine < 0 {
		startLine = 0
	}
	endLine := startLine + (t.height - 2)
	if endLine > len(t.lines) {
		endLine = len(t.lines)
	}

	// Draw lines
	for i := startLine; i < endLine; i++ {
		if i >= len(t.lines) {
			break
		}

		line := t.lines[i]
		if i == t.selected {
			// Highlight selected line
			fmt.Printf("\x1b[7m%-*s\x1b[0m\n", t.width, line)
		} else {
			fmt.Printf("%s\n", line)
		}
	}

	// Fill remaining space
	for i := endLine - startLine; i < t.height-1; i++ {
		fmt.Printf("~\n")
	}

	// Status bar
	percentage := 1
	if len(t.lines) > 0 {
		percentage = (t.selected * 100) / len(t.lines)
	}
	status := fmt.Sprintf("%d%%", percentage)
	if t.filename != "" {
		status = fmt.Sprintf("%d%% %s", percentage, t.filename)
	}

	// Invert colors for status bar
	fmt.Printf("\x1b[7m%-*s\x1b[0m", t.width, status)
	fmt.Print("\r\n") // Add newline for proper display
}
